/* ---------- Banner ---------- */
/* an announcement on a tint of its tone: an eyebrow, a title, a line of text and its actions on the left, and one of four line
   drawings on the right, drawn as a hairline with a few construction lines, the way Blueprint draws everything. Each tone
   names three colours: --bnx-m draws the art (3:1 on the fill), --bnx-c writes the eyebrow (4.5:1) and --bnx-f is what
   the fill is a tint of. The fill is solid, so the dismiss button and the art's own faces can wear it too */
.bnx-slot{width:100%}
.bnx{position:relative;width:100%;min-height:176px;display:flex;flex-direction:column;justify-content:center;overflow:hidden;border-radius:var(--r-card);container:bnx/inline-size;isolation:isolate;
  --bnx-m:var(--accent-mark);--bnx-c:var(--accent-fg);--bnx-f:var(--accent);--bnx-k:10%;--bnx-ka:var(--bnx-k);
  --bnx-bg:color-mix(in srgb,var(--bnx-f) var(--bnx-ka),var(--surface));
  background:var(--bnx-bg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--bnx-m) 14%,transparent);transition:background-color var(--t-slow) var(--ease),box-shadow var(--t-slow) var(--ease)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .bnx{--bnx-k:14%}}
:root[data-theme="dark"] .bnx{--bnx-k:14%}
.bnx[data-tone="neutral"]{--bnx-m:var(--muted);--bnx-c:var(--fg2);--bnx-bg:var(--chip)}
.bnx[data-tone="blue"]{--bnx-m:var(--pb);--bnx-c:var(--pb);--bnx-f:var(--pb);--bnx-ka:var(--bnx-k)}
.bnx[data-tone="violet"]{--bnx-m:var(--pl);--bnx-c:var(--pl);--bnx-f:var(--pl);--bnx-ka:var(--bnx-k)}
.bnx[data-tone="green"]{--bnx-m:var(--pm);--bnx-c:var(--pm);--bnx-f:var(--pm);--bnx-ka:var(--bnx-k)}
.bnx[data-tone="amber"]{--bnx-m:var(--py);--bnx-c:var(--py);--bnx-f:var(--py);--bnx-ka:var(--bnx-k)}
/* the text keeps clear of the art: its right padding is the art's width */
.bnx-tx{position:relative;z-index:1;display:flex;flex-direction:column;align-items:flex-start;padding:var(--s-5) calc(min(42%,300px) + var(--s-2)) var(--s-5) var(--s-6)}
.bnx-eb{font-size:12px;font-weight:500;line-height:16px;color:var(--bnx-c);transition:color var(--t-slow) var(--ease)}
.bnx-t{margin:var(--s-2) 0 0;font-size:14px;font-weight:500;line-height:20px;color:var(--fg);text-wrap:balance}
.bnx-d{margin:var(--s-1) 0 0;font-size:13px;line-height:20px;color:var(--fg2);text-wrap:pretty}
.bnx-acts{display:flex;flex-wrap:wrap;align-items:center;gap:var(--s-2) var(--s-4);margin-top:var(--s-4)}
.bnx-lk{display:inline-flex;align-items:center;height:28px;font-size:13px;color:var(--fg);text-decoration:underline;text-decoration-color:color-mix(in srgb,currentColor 35%,transparent);text-underline-offset:3px;transition:text-decoration-color var(--t-fast)}
@media (hover:hover) and (pointer:fine){.bnx-lk:hover{text-decoration-color:currentColor}}
.bnx-x{position:absolute;top:var(--s-2);right:var(--s-2);z-index:2;width:28px;height:28px;background:var(--bnx-bg)}
@media (hover:hover) and (pointer:fine){.bnx-x:hover{background:color-mix(in srgb,var(--fg) 8%,var(--bnx-bg))}}
/* the art: a 240 by 160 drawing at its own size in the middle of the area on the right, cropped by it and faded in from the
   text's side, so a narrower banner shows less of it rather than a smaller one */
.bnx-art{position:absolute;top:0;right:0;bottom:0;width:min(42%,300px);overflow:hidden;pointer-events:none;-webkit-mask-image:linear-gradient(90deg,transparent,#000 var(--s-8));mask-image:linear-gradient(90deg,transparent,#000 var(--s-8))}
.bnx-svg{position:absolute;left:50%;top:50%;width:240px;height:160px;margin:-80px 0 0 -120px;overflow:visible;display:block}
.bnx-svg .ln{fill:none;stroke:var(--bnx-m);stroke-width:1;stroke-linejoin:round;stroke-dasharray:1 1;stroke-dashoffset:0;animation:bnxdraw 1.1s var(--ease) calc(160ms + var(--d,0) * 60ms) backwards}
.bnx-svg .ac{stroke-width:1.5}
.bnx-svg .gd{fill:none;stroke:var(--bnx-m);stroke-width:1;stroke-dasharray:2 3;opacity:.45;animation:bnxfade .9s var(--ease) 60ms backwards}
/* the faces under the lines wear the fill, so what is in front hides what is behind once it is drawn */
.bnx-svg .pl{fill:var(--bnx-bg);stroke:none;animation:bnxfade .6s var(--ease) .5s backwards}
.bnx-svg .hub{fill:var(--bnx-m);animation:bnxfade .4s var(--ease) 1s backwards}
@keyframes bnxdraw{from{stroke-dashoffset:1}}
@keyframes bnxfade{from{opacity:0}}
/* under the pointer the drawing pulls apart a little: each part moves by its depth (--z), with no blur and nothing that loops */
.bnx-svg .z{transition:transform var(--t-slow) var(--ease)}
@media (hover:hover) and (pointer:fine){.bnx:hover .bnx-svg .z{transform:translate(calc(var(--z,0) * 1px),calc(var(--z,0) * -2.5px))}}
/* dismissed: the banner leaves, and a quiet line with Undo keeps its place (held at its height, so it stays centred) */
.bnx-gone{display:flex;align-items:center;justify-content:center;gap:var(--s-3);min-height:44px;font-size:13px;color:var(--fg2)}
/* a phone, or any narrow column: the art becomes a shorter strip across the top that fades out before the text starts,
   so nothing is drawn behind the words. The drawing is shown at three quarters, with its lines thickened to stay a hairline */
@container bnx (max-width:479px){
  .bnx-art{left:0;bottom:auto;width:auto;height:88px;-webkit-mask-image:linear-gradient(#000 36px,transparent 84px);mask-image:linear-gradient(#000 36px,transparent 84px)}
  .bnx-svg{top:54px;transform:scale(.72)}
  .bnx-svg :is(.ln,.gd){stroke-width:1.4}
  .bnx-svg .ac{stroke-width:2}
  .bnx-tx{padding:84px var(--s-5) var(--s-5)}
}
@media (prefers-reduced-motion:reduce){.bnx-svg *{animation:none!important}.bnx-svg .z{transform:none!important}}
/* Blueprint: square, with a hairline edge in its tone, and the eyebrow as a small capital label */
:root:not([data-style="soft"]) .bnx:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--bnx-m) 45%,var(--line))}
:root:not([data-style="soft"]) .bnx:is(:not([data-tone]),[data-tone="accent"]):not(:where([data-style="soft"],[data-style="soft"] *)){--bnx-ka:20%}
@media (prefers-color-scheme:dark){:root:not([data-style="soft"]):not([data-theme="light"]) .bnx:is(:not([data-tone]),[data-tone="accent"]):not(:where([data-style="soft"],[data-style="soft"] *)){--bnx-ka:9%}}
:root:not([data-style="soft"])[data-theme="dark"] .bnx:is(:not([data-tone]),[data-tone="accent"]):not(:where([data-style="soft"],[data-style="soft"] *)){--bnx-ka:9%}
:root:not([data-style="soft"]) .bnx-eb:not(:where([data-style="soft"],[data-style="soft"] *)){font-size:11px;letter-spacing:.06em;text-transform:uppercase}

/* the four drawings, each 240 by 160 and written as plain paths: layers (three plates of a stack, pulled apart), steps (a
   staircase climbing to a flag), nodes (a small graph standing on a floor grid) and grid (a floor that bends up towards its
   vanishing point, with one tile raised). .ln lines draw themselves in, in the order --d gives; .gd are the construction
   lines, dashed, which fade in; .pl are faces in the banner's fill that hide what is behind them; each .z group moves by
   its depth --z under the pointer */
const BNX_ART = {
  layers:"<g class=\"gds\"><path class=\"gd\" d=\"M92 34V124M208 34V124M150 87.5V159.5\"/><path class=\"gd\" d=\"M222 48V104M218 48h8M218 104h8\"/></g><g class=\"z\" style=\"--z:0\"><path class=\"pl\" d=\"M150 70.5L208 104L208 110L150 143.5L92 110L92 104Z\"/><path class=\"ln\" style=\"--d:0\" pathLength=\"1\" d=\"M150 70.5L208 104L150 137.5L92 104Z\"/><path class=\"ln\" style=\"--d:1\" pathLength=\"1\" d=\"M92 104L92 110L150 143.5L208 110L208 104\"/><path class=\"ln\" style=\"--d:2\" pathLength=\"1\" d=\"M150 137.5L150 143.5\"/></g><g class=\"z\" style=\"--z:1\"><path class=\"pl\" d=\"M150 42.5L208 76L208 82L150 115.5L92 82L92 76Z\"/><path class=\"ln\" style=\"--d:3\" pathLength=\"1\" d=\"M150 42.5L208 76L150 109.5L92 76Z\"/><path class=\"ln\" style=\"--d:4\" pathLength=\"1\" d=\"M92 76L92 82L150 115.5L208 82L208 76\"/><path class=\"ln\" style=\"--d:5\" pathLength=\"1\" d=\"M150 109.5L150 115.5\"/></g><g class=\"z\" style=\"--z:2\"><path class=\"pl\" d=\"M150 14.5L208 48L208 54L150 87.5L92 54L92 48Z\"/><path class=\"ln\" style=\"--d:6\" pathLength=\"1\" d=\"M150 14.5L208 48L150 81.5L92 48Z\"/><path class=\"ln\" style=\"--d:7\" pathLength=\"1\" d=\"M92 48L92 54L150 87.5L208 54L208 48\"/><path class=\"ln\" style=\"--d:8\" pathLength=\"1\" d=\"M150 81.5L150 87.5\"/><path class=\"ln ac\" style=\"--d:9\" pathLength=\"1\" d=\"M150 28.5L184 48L150 67.5L116 48Z\"/></g>",
  steps:"<g class=\"gds\"><path class=\"gd\" d=\"M100 157L179.7 111M77.5 146L167.6 26.8\"/></g><g class=\"z\" style=\"--z:0\"><path class=\"pl\" d=\"M126 28L155.4 45L138.1 55L108.7 38Z\"/><path class=\"ln\" style=\"--d:0\" pathLength=\"1\" d=\"M126 28L155.4 45L138.1 55L108.7 38Z\"/><path class=\"pl\" d=\"M108.7 102L138.1 119L138.1 55L108.7 38Z\"/><path class=\"ln\" style=\"--d:1\" pathLength=\"1\" d=\"M108.7 102L138.1 119L138.1 55L108.7 38Z\"/><path class=\"pl\" d=\"M155.4 109L138.1 119L138.1 55L155.4 45Z\"/><path class=\"ln\" style=\"--d:2\" pathLength=\"1\" d=\"M155.4 109L138.1 119L138.1 55L155.4 45Z\"/><path class=\"pl\" d=\"M108.7 54L138.1 71L120.8 81L91.4 64Z\"/><path class=\"ln\" style=\"--d:3\" pathLength=\"1\" d=\"M108.7 54L138.1 71L120.8 81L91.4 64Z\"/><path class=\"pl\" d=\"M91.4 112L120.8 129L120.8 81L91.4 64Z\"/><path class=\"ln\" style=\"--d:4\" pathLength=\"1\" d=\"M91.4 112L120.8 129L120.8 81L91.4 64Z\"/><path class=\"pl\" d=\"M138.1 119L120.8 129L120.8 81L138.1 71Z\"/><path class=\"ln\" style=\"--d:5\" pathLength=\"1\" d=\"M138.1 119L120.8 129L120.8 81L138.1 71Z\"/><path class=\"pl\" d=\"M91.4 80L120.8 97L103.5 107L74 90Z\"/><path class=\"ln\" style=\"--d:6\" pathLength=\"1\" d=\"M91.4 80L120.8 97L103.5 107L74 90Z\"/><path class=\"pl\" d=\"M74 122L103.5 139L103.5 107L74 90Z\"/><path class=\"ln\" style=\"--d:7\" pathLength=\"1\" d=\"M74 122L103.5 139L103.5 107L74 90Z\"/><path class=\"pl\" d=\"M120.8 129L103.5 139L103.5 107L120.8 97Z\"/><path class=\"ln\" style=\"--d:8\" pathLength=\"1\" d=\"M120.8 129L103.5 139L103.5 107L120.8 97Z\"/><path class=\"pl\" d=\"M74 106L103.5 123L86.2 133L56.7 116Z\"/><path class=\"ln\" style=\"--d:9\" pathLength=\"1\" d=\"M74 106L103.5 123L86.2 133L56.7 116Z\"/><path class=\"pl\" d=\"M56.7 132L86.2 149L86.2 133L56.7 116Z\"/><path class=\"ln\" style=\"--d:10\" pathLength=\"1\" d=\"M56.7 132L86.2 149L86.2 133L56.7 116Z\"/><path class=\"pl\" d=\"M103.5 139L86.2 149L86.2 133L103.5 123Z\"/><path class=\"ln\" style=\"--d:11\" pathLength=\"1\" d=\"M103.5 139L86.2 149L86.2 133L103.5 123Z\"/></g><g class=\"z\" style=\"--z:2\"><path class=\"ln ac\" style=\"--d:12\" pathLength=\"1\" d=\"M132.1 41.5V17.5h14l-4 5 4 5h-14\"/></g>",
  nodes:"<g class=\"gds\"><path class=\"gd\" d=\"M150 46L66.9 94M150 46L233.1 94M170.8 58L87.6 106M129.2 58L212.4 106M191.6 70L108.4 118M108.4 70L191.6 118M212.4 82L129.2 130M87.6 82L170.8 130M233.1 94L150 142M66.9 94L150 142\"/></g><g class=\"z\" style=\"--z:0\"><path class=\"gd\" d=\"M170.8 58V40\"/><path class=\"gd\" d=\"M166.8 55.7L174.8 60.3M174.8 55.7L166.8 60.3\"/><path class=\"gd\" d=\"M212.4 106V92\"/><path class=\"gd\" d=\"M208.4 103.7L216.4 108.3M216.4 103.7L208.4 108.3\"/><path class=\"gd\" d=\"M87.6 82V68\"/><path class=\"gd\" d=\"M83.6 79.7L91.6 84.3M91.6 79.7L83.6 84.3\"/><path class=\"gd\" d=\"M129.2 130V110\"/><path class=\"gd\" d=\"M125.2 127.7L133.2 132.3M133.2 127.7L125.2 132.3\"/><path class=\"gd\" d=\"M150 94V60\"/><path class=\"gd\" d=\"M146 91.7L154 96.3M154 91.7L146 96.3\"/></g><g class=\"z\" style=\"--z:1\"><path class=\"ln\" style=\"--d:0\" pathLength=\"1\" d=\"M170.8 40L150 60\"/><path class=\"ln\" style=\"--d:1\" pathLength=\"1\" d=\"M212.4 92L150 60\"/><path class=\"ln\" style=\"--d:2\" pathLength=\"1\" d=\"M87.6 68L150 60\"/><path class=\"ln\" style=\"--d:3\" pathLength=\"1\" d=\"M150 60L129.2 110\"/><path class=\"ln\" style=\"--d:4\" pathLength=\"1\" d=\"M170.8 40L212.4 92\"/><path class=\"ln\" style=\"--d:5\" pathLength=\"1\" d=\"M87.6 68L129.2 110\"/></g><g class=\"z\" style=\"--z:2\"><circle class=\"pl\" cx=\"170.8\" cy=\"40\" r=\"6\"/><circle class=\"ln\" style=\"--d:6\" pathLength=\"1\" cx=\"170.8\" cy=\"40\" r=\"6\"/><circle class=\"pl\" cx=\"212.4\" cy=\"92\" r=\"7\"/><circle class=\"ln\" style=\"--d:7\" pathLength=\"1\" cx=\"212.4\" cy=\"92\" r=\"7\"/><circle class=\"pl\" cx=\"87.6\" cy=\"68\" r=\"6\"/><circle class=\"ln\" style=\"--d:8\" pathLength=\"1\" cx=\"87.6\" cy=\"68\" r=\"6\"/><circle class=\"pl\" cx=\"129.2\" cy=\"110\" r=\"6\"/><circle class=\"ln\" style=\"--d:9\" pathLength=\"1\" cx=\"129.2\" cy=\"110\" r=\"6\"/><circle class=\"pl\" cx=\"150\" cy=\"60\" r=\"8\"/><circle class=\"ln ac\" style=\"--d:10\" pathLength=\"1\" cx=\"150\" cy=\"60\" r=\"8\"/><circle class=\"gd\" cx=\"150\" cy=\"60\" r=\"14\"/><circle class=\"hub\" cx=\"150\" cy=\"60\" r=\"2\"/></g>",
