DM.def('banner', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{x}', I('x'));
  const slot = $('.bnx-slot', r) || r, root = $('.bnx', r), art = $('.bnx-art', root), gone = $('.bnx-gone', r);
  const xB = $('.bnx-x', root), undoB = gone && $('.bnx-undo', gone);
  const T = { eb:$('.bnx-eb>span', root), t:$('.bnx-t>span', root), d:$('.bnx-d>span', root), a:$('.bnx-go>span', root), s:$('.bnx-lk>span', root) };
  // the drawing named by data-art; drawing it again plays its entrance again
  const draw = () => { const k = root.dataset.art; art.innerHTML = BNX_ART[k] ? `<svg class="bnx-svg" viewBox="0 0 240 160" width="240" height="160" focusable="false">${BNX_ART[k]}</svg>` : ''; };
  draw();
  // Dismiss: the banner leaves and the line with Undo takes its place, in the height the banner had, so it stays where it was.
  // The focus follows to Undo, and back to Dismiss after Undo, so a keyboard never loses its place
  const dismiss = () => {
    if (root.hidden || root.classList.contains('leave')) return;
    const back = root.contains(document.activeElement);
    hold(slot); root.classList.add('leave');
    c.later(REDUCE ? 0 : 320, () => { root.classList.remove('leave'); root.hidden = true; if (!gone) return; gone.hidden = false; enter(gone); if (back) undoB.focus({ preventScroll:true }); });
  };
  const undo = () => {
    const back = gone.contains(document.activeElement);
    gone.hidden = true; root.hidden = false; release(slot); enter(root); draw();
    if (back) xB.focus({ preventScroll:true });
  };
  xB.onclick = dismiss;
  if (undoB) undoB.onclick = undo;

  // the preview's banners, one after another: the tone, the drawing and the words change in place
  const P = [
    { tone:'accent', art:'layers', eb:'New', t:'Memory that carries across threads', d:'Agents keep what they learn about your project, so you only explain things once.', a:'Turn on memory', s:'What it keeps' },
    { tone:'violet', art:'nodes', eb:'Beta', t:'Connect your tools in one place', d:'Linear, GitHub and Slack in one list, with access you can scope for each agent.', a:'Connect a tool', s:'Read the docs' },
    { tone:'green', art:'steps', eb:'Guide', t:'Set up your first automation', d:'Five short steps, about ten minutes. The agent can do most of them for you.', a:'Start the guide', s:'Maybe later' },
    { tone:'amber', art:'grid', eb:'Heads-up', t:'Maintenance on Sunday, 02:00 UTC', d:'Agents pause for about an hour, and queued runs pick up where they left off.', a:'Add to calendar', s:'Status page' }
  ];
  const show = (p, now) => { root.dataset.tone = p.tone; root.dataset.art = p.art; for (const k in T) if (T[k]) now ? T[k].textContent = p[k] : swap(T[k], p[k]); draw(); };
  // three banners, then the last one is dismissed. A story that plays to the end leaves the next run one banner further on,
  // so every drawing comes round. A click, a key or the focus of yours stops it where it is, and a mouse resting on it holds it
  if (r === c.st && c.card){
    const n = c.card._bnx || 0;
    if (n) show(P[n], true);
    c.story(async s => {
      await s.beat(8);
      show(P[(n + 1) % P.length]); await s.beat(8);
      show(P[(n + 2) % P.length]); await s.beat(8);
      await s.tap(xB); s.away(); await s.beat(5);
      c.card._bnx = (n + 1) % P.length;
    });
  }
});
